// Bridge for app versions up to 1.1.37. Their translator prompt
// (translator_prompt.dart, mobile beb8233) let the model answer questions
// about words — «Как будет по-немецки слово счёт?» came back as «…Rechnung»
// or repeated in Russian — and refuse «переводи на английский» with "Я
// перевожу только между русским и немецким…". The app's prompt got rule 5,
// the ANY-language note and "Never refuse" (mobile be6076b); until installed
// apps update, translator sessions get the old prompt upgraded here to the
// new one byte for byte (the spec checks it against prompts generated by both
// versions of the Dart code). A prompt this does not fully recognise — the
// new one, a future one, the assistant's — passes unchanged.
// Remove once translator sessions from 1.1.37 and older are gone.

const OLD_PROMPT_START =
  'YOU ARE A LIVE TRANSLATION MACHINE. NOT AN ASSISTANT. NOT A CHATBOT.';
const NEW_PROMPT_MARK =
  'Questions about words and languages are conversation too';

const RULE_2_END = 'the conversation — translate them.\n3.';
const RULE_4_END = 'Keep names, numbers, places exact.\n\n';
const LANGUAGE_COMMAND_END = 'ISO 639-1 code of X.\n';

function rule5(direction: string): string {
  return (
    '5. Questions about words and languages are conversation too: "как будет ' +
    'по-немецки «счёт»?", "как сказать «спасибо»?", "что значит «Bahnhof»?", ' +
    '"how do you say …?". Translate the question itself into the other ' +
    'language and keep the word being asked about exactly as it was said — ' +
    'only that word: everything else, the name of the language included, is ' +
    `translated. ${direction}` +
    'Never answer such a question and never repeat it in its own language. ' +
    'Example (Russian–German): «Как по-немецки будет «вилка»?» → ' +
    '"Wie sagt man «вилка» auf Deutsch?"\n\n'
  );
}

const occursOnce = (text: string, part: string) =>
  text.split(part).length === 2;

export function upgradeLegacyTranslatorPrompt(text: string): string {
  if (!text.startsWith(OLD_PROMPT_START) || text.includes(NEW_PROMPT_MARK)) {
    return text;
  }
  if (
    ![RULE_2_END, RULE_4_END, LANGUAGE_COMMAND_END].every((part) =>
      occursOnce(text, part),
    )
  ) {
    return text;
  }
  // "One speaks Russian, the other speaks German." — absent until the other
  // person's language is chosen, and then the new prompt has no direction.
  const pair = /One speaks (.+?), the other speaks (.+?)\. /.exec(text);
  const direction = pair
    ? `A ${pair[1]} question about a ${pair[2]} word is still ${pair[1]} ` +
      `speech, so it is said in ${pair[2]} — and a ${pair[2]} question about ` +
      `a ${pair[1]} word is said in ${pair[1]}. `
    : '';
  // Function replacements: language names must not be read as `$` patterns.
  return text
    .replace(
      RULE_2_END,
      () =>
        'the conversation — translate them. Never refuse and never explain ' +
        'what you do or which languages you translate.\n3.',
    )
    .replace(
      RULE_4_END,
      () => 'Keep names, numbers, places exact.\n' + rule5(direction),
    )
    .replace(
      LANGUAGE_COMMAND_END,
      () =>
        'ISO 639-1 code of X. This works for ANY language, not only the ' +
        'current two: "переводи на английский" in a Russian–German ' +
        'conversation switches to English.\n',
    );
}

/** A session.update with its translator instructions upgraded. */
export function withUpgradedTranslatorPrompt<
  T extends { type?: string; session?: unknown },
>(ev: T): T {
  if (ev?.type !== 'session.update') return ev;
  const session = ev.session as { instructions?: unknown } | undefined;
  if (typeof session?.instructions !== 'string') return ev;
  const instructions = upgradeLegacyTranslatorPrompt(session.instructions);
  if (instructions === session.instructions) return ev;
  return { ...ev, session: { ...session, instructions } };
}
